def copiar_a_caracteristicas(apps, schema_editor):
    """La lista `features` y el texto `dimensions` pasan a la sección Características
    (texto con formato), para que nada se pierda al dejar de mostrarlos."""
    Producto = apps.get_model('paginaweb', 'PaginawebProducto')
    for p in Producto.objects.using(schema_editor.connection.alias).all().iterator():
        partes = []
        items = [str(f).strip() for f in (p.features or []) if str(f).strip()]
        if items:
            partes.append('\n'.join(f'- {f}' for f in items))
        if (p.dimensions or '').strip():
            partes.append(f'**Dimensiones:** {p.dimensions.strip()}')
        if partes and not p.characteristics:
            p.characteristics = '\n\n'.join(partes)
            p.save(using=schema_editor.connection.alias, update_fields=['characteristics'])


